// WhoIsJohnny? Nobodies: the machine.
// Every Nobody comes from its number. Same number, same figure, same name. Always.
// Used by the web page (index.html) and by the server code (functions/api).

var HEADS=['#9b9b9b','#e8832a','#18a3a3','#f2c6a0','#2f9e5b','#f3d34a','#e98c7b','#7aa7e8','#c7a3e8','#d9d9d9','#f08fb0','#8fd16a'];
