  var SA=isSanta(seed); if(SA){ body='#c93c2b'; head=['#f2c6a0','#e98c7b'][seed%2]; paper=['#e8f1f0','#eef3f6'][seed%2]; }
  var R=f(36,50),cx=100,cy=f(88,100),shape=int(5);
  var vs=[1,1,1.15,.85,1.05][shape];
  var top=cy-R*vs,btm=cy+R*vs;
