  if(X){ s+='<g transform="translate(9 22) scale(.91)">'; for(var sn=0;sn<26;sn++) s+='<circle cx="'+(xr()*200).toFixed(1)+'" cy="'+(xr()*262).toFixed(1)+'" r="'+(1.6+xr()*2.6).toFixed(1)+'" fill="#ffffff" stroke="#b9c7d0" stroke-width="1"/>'; }
  var bt=btm-9,bb=238,bw=f(58,96),bshape=int(4),bodyEl,clipEl,pts;
