    if(gt===1){s+='<rect x="'+(g1[0]-g1[1]-5).toFixed(1)+'" y="'+(ey-g1[1]-5).toFixed(1)+'" width="'+(2*g1[1]+10).toFixed(1)+'" height="'+(2*g1[1]+10).toFixed(1)+'" fill="none" stroke="'+gc+'" stroke-width="3"/><rect x="'+(g2[0]-g2[1]-5).toFixed(1)+'" y="'+(ey-g2[1]-5).toFixed(1)+'" width="'+(2*g2[1]+10).toFixed(1)+'" height="'+(2*g2[1]+10).toFixed(1)+'" fill="none" stroke="'+gc+'" stroke-width="3"/>'}
    else{s+='<circle cx="'+g1[0].toFixed(1)+'" cy="'+ey.toFixed(1)+'" r="'+(g1[1]+5).toFixed(1)+'" fill="none" stroke="'+gc+'" stroke-width="'+(gt===2?4.5:3)+'"/><circle cx="'+g2[0].toFixed(1)+'" cy="'+ey.toFixed(1)+'" r="'+(g2[1]+5).toFixed(1)+'" fill="none" stroke="'+gc+'" stroke-width="'+(gt===2?4.5:3)+'"/>'}
    s+='<path d="M'+(g1[0]+g1[1]+5).toFixed(1)+' '+ey.toFixed(1)+' L'+(g2[0]-g2[1]-5).toFixed(1)+' '+ey.toFixed(1)+'" stroke="'+gc+'" stroke-width="3"/>';
