// ---- Stories ---------------------------------------------------------------
// One short story per Nobody. Later litters fall back to a shared line on the page.
var STORIES={
1:'Raised both arms once to say something. Forgot what. Kept the arms up anyway.',
2:'Wears a tie every day in case there is a meeting. There has never been a meeting.',
3:'Has a name tag. Nobody has read it. Raskut prefers it that way.',
4:'Bought a top hat for a special occasion. Is still waiting for the occasion.',
5:'Has one eye and sees everything. Has decided not to mention most of it.',
6:'Sticks its tongue out at Mondays. Mondays have not noticed.',
7:'Practised a smile for three weeks. This is the result.',
8:'Was surprised once in 2019. Has not fully recovered.',
9:'Very happy. Does not know why. Has stopped asking.',
10:'The hair does this by itself. Jikkem has tried talking to it.',
11:'Wears a beanie indoors. Says it helps with thinking. Has not thought of anything yet.',
12:'Stands very straight. Was told to once. Nobody said it could stop.',
13:'Reads the terms and conditions. All of them. Every time.',
14:'Laughs at jokes a little too early. Sometimes before they are told.',
15:'Three eyes, one beanie. Has made peace with the maths.',
16:'Rolled here. Does not remember from where.',
17:'Is not angry. This is just the face. Please stop asking.',
18:'Is not sad. Is simply done with the week. It is Tuesday.',
19:'Works in middle management. Of what, nobody knows.',
20:'Has heard about fun. Remains unconvinced.',
21:'Dressed up for a party. The party was last week.',
22:'Found the crown on the ground. Nobody has claimed it. Bizidi has stopped looking.',
23:'Worries about things that have not happened yet. Is right about some of them.',
24:'Thinks it left the oven on. Does not have an oven.',
25:'Was in a band once. The band does not remember.',
26:'Royalty, apparently. Has not been told of what.',
27:'Has a curl that points at things. Bugegi does not agree with it.',
28:'Tall hat, long hair, three eyes. Takes up more room than planned.',
29:'Takes very long naps. Woke up for this, though.',
30:'Looks at you with one eye. That is plenty.',
31:'Sticks its tongue out in every photo. Every single one.',
32:'Wore its best tie to the dentist. The dentist noticed.',
33:'Started yawning in 2024. Is still yawning. Pacing itself.',
34:'Reads the small print with big glasses. Has found nothing yet.',
35:'One eye, one curl, one opinion. Keeps all three to itself.',
36:'Had a fright in 2021. The hair stayed that way.',
37:'Round in shape and in outlook. Rolls with things.',
38:'Looks like it has a plan. Does not have a plan.',
39:'Counts sheep at night. Gets three times as many.',
40:'Formal on the bottom. Not on top. Has its reasons.',
41:'Saw the price of coffee. Has looked like this ever since.',
42:'Top hat, tongue out. Elegant, but only up to a point.',
43:'The crown floats. Nuntut does not know how. Nobody has asked the crown.',
44:'Wears polka dots to funerals. Has been to none.',
45:'Arms up. Not a robbery. Just a stretch that went on.',
46:'Named Happes. Not especially happy. Not especially anything.',
47:'Just remembered something embarrassing from 2009. Right now, actually.',
48:'Sat down once. Has not seen a reason to get up.',
49:'Wears a beanie indoors. Has never been cold. Likes to be ready.',
50:'Last one on the first shelf. Wears the top hat to make up for it.',
9001:'Was told it would snow. It did. Zobi has not commented.',
9002:'Applied to pull a sleigh. Was not called back. Still smiling about it, which is worse.',
9003:'Worked one season in a workshop. Made one thing. Will not say what.',
9004:'Saw Santa once. Has looked like this ever since.',
9005:'Was the top of a tree for eleven years. Now retired. Keeps the star on, just in case.',
9006:'Waits by the chimney every year. Does not have a chimney.',
9007:'Keeps the naughty list. Has not checked it twice. Once seemed enough.',
9008:'Reindeer on weekends. Accountant during the week. Nobody has asked which is the real one.',
9009:'Ate the cookies that were left out. They were not for Rumpo. Rumpo knew that.',
9010:'Thinks it is the brightest thing in the room. In a dark room, this is correct.',
9011:'Got the suit for one party in 2019. Has not found a reason to take it off.',
9012:'Is not Santa. Has stopped saying so. It only made the children sadder.',
9013:'Built on a Tuesday. Expects to leave in April. Has made no other plans.',
9014:'Wears a hat in case it gets cold. It has never once been warm.'
};
export function storyOf(n){ return STORIES[n] || null; }
